<?php
require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/auth.php';
$pdo=getConnection(); $erro=''; $ok='';
$tipos=$pdo->query('SELECT id_tipo,nome_tipo FROM tipo_ocorrencia ORDER BY nome_tipo')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){
 requireLogin();
 $tipo=(int)($_POST['id_tipo']??0); $desc=trim($_POST['descricao']??''); $lat=(float)($_POST['latitude']??0); $lng=(float)($_POST['longitude']??0); $data=$_POST['data']??''; $hora=$_POST['horario']??'';
 if(!$tipo||!$data||!$hora||!$lat||!$lng){$erro='Preencha todos os campos obrigatórios e informe uma localização válida.';}
 elseif($lat<-90||$lat>90||$lng<-180||$lng>180){$erro='Latitude ou longitude inválida.';}
 elseif(mb_strlen($desc)>1000){$erro='A descrição deve ter no máximo 1000 caracteres.';}
 else{ $st=$pdo->prepare('INSERT INTO ocorrencia(id_usuario,id_tipo,descricao,latitude,longitude,data,horario,status,fonte) VALUES(?,?,?,?,?,?,?,"pendente","usuario")'); $st->execute([currentUser()['id_usuario'],$tipo,$desc,$lat,$lng,$data,$hora]); $ok='Ocorrência enviada. Ela ficará pendente até análise administrativa.'; }
}
$recentes=$pdo->query("SELECT o.id_ocorrencia,o.descricao,o.latitude,o.longitude,o.data,o.horario,o.status,t.nome_tipo FROM ocorrencia o JOIN tipo_ocorrencia t ON t.id_tipo=o.id_tipo WHERE o.status='aprovada' ORDER BY o.data DESC,o.horario DESC LIMIT 20")->fetchAll();
$page_title='SafeRoute — Ocorrências'; $extra_css=['https://unpkg.com/leaflet@1.9.4/dist/leaflet.css']; $extra_js=['https://unpkg.com/leaflet@1.9.4/dist/leaflet.js'];
require_once __DIR__.'/../includes/header.php'; require_once __DIR__.'/../includes/navbar.php';
?>
<main class="container page-main"><section class="page-hero"><span class="eyebrow">OCORRÊNCIAS</span><h1>Registros de segurança</h1><p>Consulte ocorrências aprovadas e, se estiver conectado, envie um novo relato.</p></section>
<?php if($erro): ?><div class="alert alert-error">⚠️ <?= htmlspecialchars($erro) ?></div><?php endif; ?><?php if($ok): ?><div class="alert alert-success">✅ <?= htmlspecialchars($ok) ?></div><?php endif; ?>
<div class="content-grid"><section class="card form-card"><h2>Registrar ocorrência</h2><?php if(!isLoggedIn()): ?><p>Faça login para registrar uma ocorrência.</p><a class="btn btn-primary" href="<?= BASE_URL ?>pages/login.php">Entrar</a><?php else: ?><p class="muted">O registro será enviado como pendente para análise.</p><form method="post" class="form-grid"><div class="form-group"><label class="form-label">Tipo</label><select name="id_tipo" class="form-control" required><option value="">Selecione</option><?php foreach($tipos as $t): ?><option value="<?= $t['id_tipo'] ?>"><?= htmlspecialchars($t['nome_tipo']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label class="form-label">Data</label><input type="date" name="data" class="form-control" value="<?= date('Y-m-d') ?>" required></div><div class="form-group"><label class="form-label">Horário</label><input type="time" name="horario" class="form-control" value="<?= date('H:i') ?>" required></div><div class="form-group"><label class="form-label">Latitude</label><input id="lat" type="number" step="any" name="latitude" class="form-control" placeholder="Ex.: -8.7612" required></div><div class="form-group"><label class="form-label">Longitude</label><input id="lng" type="number" step="any" name="longitude" class="form-control" placeholder="Ex.: -63.9004" required></div><div class="form-group full"><label class="form-label">Descrição</label><textarea name="descricao" class="form-control" rows="4" maxlength="1000" placeholder="Descreva o ocorrido..."></textarea></div><div class="full"><button type="button" class="btn btn-secondary" id="useLocation">📍 Usar minha localização</button> <button class="btn btn-primary">Enviar ocorrência</button></div></form><?php endif; ?></section>
<section><div id="safeMap" class="safe-map"></div><p class="map-info"><strong><?= count($recentes) ?></strong> ocorrência(s) aprovada(s) exibida(s). <span class="muted">Risco estimado baseado nos dados disponíveis.</span></p></section></div></main>
<script>document.addEventListener('DOMContentLoaded',()=>{const data=<?= json_encode($recentes,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>;const map=L.map('safeMap').setView([-8.7612,-63.9004],13);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(map);const b=[];data.forEach(o=>{const lat=+o.latitude,lng=+o.longitude;if(!isFinite(lat)||!isFinite(lng))return;const m=L.marker([lat,lng]).addTo(map);m.bindPopup('<b>'+esc(o.nome_tipo)+'</b><br>'+esc(o.descricao||'Sem descrição')+'<br><small>'+esc(o.data)+' '+esc(o.horario)+'</small>');b.push([lat,lng])});if(b.length)map.fitBounds(b,{padding:[30,30],maxZoom:16});const btn=document.getElementById('useLocation');if(btn)btn.onclick=()=>navigator.geolocation?.getCurrentPosition(p=>{lat.value=p.coords.latitude.toFixed(7);lng.value=p.coords.longitude.toFixed(7)},()=>alert('Não foi possível obter sua localização.'));});function esc(v){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}</script>
